import { test, expect, vi } from 'vitest'
import { proxy, middleware } from './proxy'
import { NextRequest } from 'next/server'

test('proxy adds X-Request-Id and logs pathname', () => {
  const consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {})

  const req1 = new NextRequest('http://localhost:3000/api/users')
  const res1 = proxy(req1)
  expect(consoleSpy).toHaveBeenCalledWith('/api/users')
  const id1 = res1.headers.get('X-Request-Id')
  expect(id1).toBeTruthy()

  const req2 = new NextRequest('http://localhost:3000/about?query=1')
  const res2 = middleware(req2)
  expect(consoleSpy).toHaveBeenCalledWith('/about')
  const id2 = res2.headers.get('X-Request-Id')
  expect(id2).toBeTruthy()

  expect(id1).not.toBe(id2)
  consoleSpy.mockRestore()
})

